content='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Background is the most frequent color; edge bars are the other repeated color.
    counts = {v: sum(row.count(v) for row in grid) for row in grid for v in row}
    bg = max(counts, key=counts.get)
    colors = {v for row in grid for v in row if v != bg}
    bar = max(colors, key=lambda v: counts[v])
    seeds = [v for v in colors if v != bar]
    if not seeds:
        return out
    seed = seeds[0]
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == seed]
    # Build the two bands of the bar color; each isolated seed projects away
    # from its band in the perpendicular direction. Seed points become 4.
    for r,c in pts:
        out[r][c] = 4
        # Seed aligned with a horizontal edge band: fill toward opposite horizontal band.
        if any(grid[r][j] == bar for j in range(w)):
            bars = [j for j in range(w) if grid[r][j] == bar]
            # if on same row as horizontal bar, the ray follows row to other endpoint
            if bars and (c < min(bars) or c > max(bars)):
                lo, hi = (0, min(bars)) if c < min(bars) else (max(bars)+1, w)
                for j in range(lo, hi):
                    if grid[r][j] == bg: out[r][j] = seed
        # Generic projection: from seed toward nearest boundary bar on row/column.
        # Edges with continuous bars determine direction. Fill the stripe bounded by them.
        if any(grid[i][c] == bar for i in range(h)):
            bars = [i for i in range(h) if grid[i][c] == bar]
            if bars:
                if r < min(bars):
                    for i in range(r+1, min(bars)): out[i][c] = seed
                elif r > max(bars):
                    for i in range(max(bars)+1, r): out[i][c] = seed
    # Identify border bars (runs) and project each marker toward its adjacent bar.
    # For each seed, extend along row/column in the direction indicated by matching
    # colored bar lying on the edge; preserve marker as 4.
    for r,c in pts:
        # Horizontal ray when a bar segment lies on left/right border in same row.
        if grid[r][0] == bar:
            for j in range(1, c):
                if grid[r][j] == bg: out[r][j] = seed
        if grid[r][w-1] == bar:
            for j in range(c+1, w-1):
                if grid[r][j] == bg: out[r][j] = seed
        if grid[0][c] == bar:
            for i in range(1, r):
                if grid[i][c] == bg: out[i][c] = seed
        if grid[h-1][c] == bar:
            for i in range(r+1, h-1):
                if grid[i][c] == bg: out[i][c] = seed
    return out
'''
