    seed = max((v for v in counts if v != bg and v != bar), key=lambda v: counts[v])
    # Each seed extends in the direction of the nearest boundary bar aligned
    # on its row/column; its own marker is the special endpoint color 4.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != seed:
                continue
            out[r][c] = 4
            # find bar runs on each edge and select aligned side
            choices = []
            if grid[0][c] == bar: choices.append((r, 'up'))
            if grid[h-1][c] == bar: choices.append((h-1-r, 'down'))
            if grid[r][0] == bar: choices.append((c, 'left'))
            if grid[r][w-1] == bar: choices.append((w-1-c, 'right'))
            if choices:
                _, d = min(choices)
                if d == 'up':
                    for rr in range(r-1, 0, -1):
                        if grid[rr][c] == bg: out[rr][c] = seed
                elif d == 'down':
                    for rr in range(r+1, h-1):
                        if grid[rr][c] == bg: out[rr][c] = seed
                elif d == 'left':
                    for cc in range(c-1, 0, -1):
                        if grid[r][cc] == bg: out[r][cc] = seed
                else:
                    for cc in range(c+1, w-1):
                        if grid[r][cc] == bg: out[r][cc] = seed
    # Dots sitting on the border are also endpoints for a ray perpendicular
    # to that border, in the direction of the bar-containing opposite side.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == seed and c == 0:
                for rr in range(r+1, h-1):
                    if grid[rr][c] == bg: out[rr][c] = seed
    return out
