    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    border = set(grid[0] + grid[-1]) | {grid[r][0] for r in range(h)} | {grid[r][-1] for r in range(h)}
    bar = max((x for x in border if x != bg), key=lambda x: counts[x])
    seed = max((x for x in counts if x != bg and x != bar), key=lambda x: counts[x])

    # Markers cast straight rays in the direction of a matching border bar.
    # When a marker shares a column with a horizontal bar, extend to that bar;
    # when it shares a row with a vertical bar, extend across that row.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != seed:
                continue
            out[r][c] = 4
            if grid[h - 1][c] == bar:
                for rr in range(r + 1, h - 1):
                    if grid[rr][c] == bg: out[rr][c] = seed
            elif grid[0][c] == bar:
                for rr in range(1, r):
                    if grid[rr][c] == bg: out[rr][c] = seed
            elif grid[r][0] == bar:
                for cc in range(1, c):
                    if grid[r][cc] == bg: out[r][cc] = seed
            elif grid[r][w - 1] == bar:
                for cc in range(c + 1, w - 1):
                    if grid[r][cc] == bg: out[r][cc] = seed

    # Each bar segment generates inward parallel lines through its positions.
    # For these examples, the first and last cell of a segment are fixed anchors;
    # interior segment positions create full-length rays of the marker color.
    for c in range(w):
