    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Infer background and bar colors from their frequency and border presence.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    edge = set(grid[0] + grid[-1]) | {grid[r][0] for r in range(h)} | {grid[r][-1] for r in range(h)}
    bar = max((v for v in edge if v != bg), key=lambda v: counts[v])
    seed = max((v for v in counts if v not in (bg, bar)), key=lambda v: counts[v])

    # Sparse cells map to the nearest bar segment, extending in the direction
    # of its edge; the sparse cell changes to 4 and the ray uses its color.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != seed:
                continue
            out[r][c] = 4
            if grid[h-1][c] == bar:
                for rr in range(r+1, h-1):
                    if grid[rr][c] == bg: out[rr][c] = seed
            elif grid[0][c] == bar:
                for rr in range(1, r):
                    if grid[rr][c] == bg: out[rr][c] = seed
            elif grid[r][0] == bar:
                for cc in range(1, c):
                    if grid[r][cc] == bg: out[r][cc] = seed
            elif grid[r][w-1] == bar:
                for cc in range(c+1, w-1):
                    if grid[r][cc] == bg: out[r][cc] = seed

    # When a seed lies directly on a boundary, continue its stripe toward the
    # opposing bar edge, since that endpoint is already supplied by the dot.
