 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    border_colors = set(grid[0] + grid[-1]) | {grid[r][0] for r in range(h)} | {grid[r][-1] for r in range(h)}
    bar = max((v for v in border_colors if v != bg), key=lambda v: counts[v])
    marker = max((v for v in counts if v not in (bg, bar)), key=lambda v: counts[v])

    # Each non-anchor cell of a boundary bar segment projects an inward ray.
    # For horizontal edge segments, rays run vertically; for vertical edges,
    # they run horizontally. The first cell in each run is the anchor.
    for edge_row in (0, h - 1):
        c = 0
        while c < w:
            if grid[edge_row][c] != bar:
                c += 1
                continue
            end = c
            while end < w and grid[edge_row][end] == bar:
                end += 1
            for col in range(c + 1, end):
                for r in range(1, h - 1):
                    if grid[r][col] == bg:
                        out[r][col] = marker
            c = end

    for edge_col in (0, w - 1):
        r = 0
        while r < h:
            if grid[r][edge_col] != bar:
                r += 1
                continue
            end = r
            while end < h and grid[end][edge_col] == bar:
                end += 1
            for row in range(r + 1, end):
                for c in range(1, w - 1):
                    if grid[row][c] == bg:
                        out[row][c] = marker
            r = end

    # Isolated markers terminate their aligned ray and become 4.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != marker:
                continue
            out[r][c] = 4
            if grid[h - 1][c] == bar:
                for rr in range(r + 1, h - 1):
                    if grid[rr][c] == bg:
                        out[rr][c] = marker
            elif grid[0][c] == bar:
                for rr in range(1, r):
                    if grid[rr][c] == bg:
                        out[rr][c] = marker
            elif grid[r][0] == bar:
                for cc in range(1, c):
                    if grid[r][cc] == bg:
                        out[r][cc] = marker
            elif grid[r][w - 1] == bar:
                for cc in range(c + 1, w - 1):
                    if grid[r][cc] == bg:
                        out[r][cc] = marker
            if c == 0:
                for rr in range(r + 1, h - 1):
                    if grid[rr][c] == bg:
                        out[rr][c] = marker
    return out
