    def runs(seq, color):
        result = []
        i = 0
        while i < len(seq):
            if seq[i] != color:
                i += 1
                continue
            j = i
            while j < len(seq) and seq[j] == color:
                j += 1
            result.append((i, j))
            i = j
        return result

    edge_vals = set(grid[0] + grid[-1]) | {grid[r][0] for r in range(h)} | {grid[r][-1] for r in range(h)}
    bar = max((v for v in edge_vals if v != bg), key=lambda v: counts[v])
    marker = max((v for v in counts if v not in (bg, bar)), key=lambda v: counts[v])
