{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    edge_colors = set(grid[0] + grid[-1]) | {grid[r][0] for r in range(h)} | {grid[r][-1] for r in range(h)}
    bar = max((value for value in edge_colors if value != background), key=lambda value: counts[value])
    marker = max((value for value in counts if value not in (background, bar)), key=lambda value: counts[value])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]

    def runs(line):
        result = []
        i = 0
        while i < len(line):
            if line[i] != bar:
                i += 1
                continue
            j = i + 1
            while j < len(line) and line[j] == bar:
                j += 1
            result.append((i, j))
            i = j
        return result

    # Paired horizontal boundary bars carry marker offsets across the board.
    top_runs = runs(grid[0])
    bottom_runs = runs(grid[-1])
    for a, b in top_runs:
        for x, y in bottom_runs:
            if b - a != y - x:
                continue
            for r, c in points:
                if x <= c < y:
                    offset = c - x
                    # From the bottom bar, draw up to its marker endpoint.
                    for rr in range(1, r):
                        if grid[rr][c] == background:
                            out[rr][c] = marker
                    out[r][c] = 4
                    # Matching stripe from the top bar runs fully to the opposite edge.
                    target = a + offset
                    for rr in range(1, h):
                        if grid[rr][target] == background:
                            out[rr][target] = marker
                elif a <= c < b:
                    offset = c - a
                    # From the top bar, draw down to the marker endpoint.
                    for rr in range(r + 1, h - 1):
                        if grid[rr][c] == background:
                            out[rr][c] = marker
                    out[r][c] = 4
                    # Matching stripe from the bottom bar runs to the opposite edge.
