                    # From the bottom bar, draw up to its marker endpoint.
                    for rr in range(1, r):
                        if grid[rr][c] == background:
                            out[rr][c] = marker
                    out[r][c] = 4
                    # Matching stripe from the top bar runs fully to the opposite edge.
                    target = a + offset
                    for rr in range(1, h):
