    # The five-cell bottom bar projects rays upward at marker offsets. The
    # dots show the offsets in the lower-left 5-column block; repeat them
    # through the open field until they meet the top boundary.
    offsets = sorted({c for r, c in points if c < 5})
    for c in offsets:
